using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.Collections.Generic;
using System.Linq;

/// <summary>Rebuilds the expanded cove dressing without overwriting imported source assets.</summary>
public static class CoastalExpansion
{
    const string Folder="Assets/Tidehaven/Expansion";
    static Transform root; static Material vertex,ground; static System.Random rng;
    static float R(float a,float b)=>Mathf.Lerp(a,b,(float)rng.NextDouble());
    static Color C(string hex){ColorUtility.TryParseHtmlString(hex,out var c);return c;}
    static Vector3 Land(float x,float z)=>new Vector3(x,CoastalIslandLayout.Height(x,z),z);
    static Mesh Save(Mesh mesh,string name){mesh.name=name;string p=Folder+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(p);if(old){EditorUtility.CopySerialized(mesh,old);Object.DestroyImmediate(mesh);return old;}AssetDatabase.CreateAsset(mesh,p);return mesh;}
    static GameObject Obj(string name,Mesh mesh,Material mat,Transform parent){var o=new GameObject(name);o.transform.SetParent(parent,false);o.AddComponent<MeshFilter>().sharedMesh=mesh;o.AddComponent<MeshRenderer>().sharedMaterial=mat;return o;}
    static Bounds Bounds(GameObject go){var rs=go.GetComponentsInChildren<Renderer>(true);var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
    static void PlaceBottom(GameObject go,float x,float z,float bury=0){go.transform.position+=Land(x,z)-new Vector3(Bounds(go).center.x,Bounds(go).min.y+bury,Bounds(go).center.z);}
    static void PlaceTemplate(GameObject source,string name,float x,float z,float height,Transform parent,bool collision=false){var go=Object.Instantiate(source,parent);go.name=name;go.SetActive(true);foreach(var col in go.GetComponentsInChildren<Collider>())Object.DestroyImmediate(col);go.transform.rotation=Quaternion.Euler(0,R(0,360),0);go.transform.localScale*=height/Bounds(go).size.y;PlaceBottom(go,x,z,.025f);if(collision){var cc=go.AddComponent<CapsuleCollider>();cc.center=go.transform.InverseTransformPoint(Land(x,z)+Vector3.up*.7f);cc.radius=.18f/go.transform.lossyScale.x;cc.height=1.4f/go.transform.lossyScale.y;}}
    static Mesh Terrain(){int nx=275,nz=238;var vs=new Vector3[(nx+1)*(nz+1)];var cs=new Color[vs.Length];var uv=new Vector2[vs.Length];var tr=new int[nx*nz*6];for(int j=0;j<=nz;j++)for(int i=0;i<=nx;i++){float x=-55+i*.4f,z=-47.6f+j*.4f;int k=j*(nx+1)+i;vs[k]=Land(x,z);uv[k]=new Vector2(x,z);float g=CoastalIslandLayout.Grass(x,z);var sand=C("#D7C89C");var grass=Color.Lerp(C("#548C44"),C("#78A652"),Mathf.PerlinNoise(x*.19f+10,z*.19f+10));cs[k]=Color.Lerp(sand,grass,g);cs[k].a=g;}int t=0;for(int j=0;j<nz;j++)for(int i=0;i<nx;i++){int k=j*(nx+1)+i;tr[t++]=k;tr[t++]=k+nx+1;tr[t++]=k+1;tr[t++]=k+1;tr[t++]=k+nx+1;tr[t++]=k+nx+2;}var mesh=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32,vertices=vs,colors=cs,uv=uv,triangles=tr};mesh.RecalculateNormals();mesh.RecalculateBounds();return Save(mesh,"MeadowCoastTerrain");}
    static Mesh Rock(int seed){var random=new System.Random(seed);int n=12;float[] radii={.75f,1f,.96f,.88f,.7f};float[] heights={0,.14f,.48f,.80f,1f};var v=new List<Vector3>();var c=new List<Color>();var t=new List<int>();for(int j=0;j<5;j++)for(int i=0;i<n;i++){float a=i*2*Mathf.PI/n;float rad=radii[j]*(.92f+(float)random.NextDouble()*.16f);v.Add(new Vector3(Mathf.Cos(a)*rad,heights[j]+(j==0?0:Mathf.Sin(a*3+seed)*.025f),Mathf.Sin(a)*rad));c.Add(Color.Lerp(C("#81928C"),C("#B2BCA3"),j/4f)*Mathf.Lerp(.93f,1.04f,(float)random.NextDouble()));}for(int j=0;j<4;j++)for(int i=0;i<n;i++){int k=j*n+i,b=j*n+(i+1)%n;t.AddRange(new[]{k,k+n,b,b,k+n,b+n});}int center=v.Count;v.Add(new Vector3(0,1.01f,0));c.Add(C("#779548"));for(int i=0;i<n;i++){c[4*n+i]=C("#72924A");t.AddRange(new[]{center,4*n+(i+1)%n,4*n+i});}var mesh=new Mesh();mesh.SetVertices(v);mesh.SetColors(c);mesh.SetTriangles(t,0);mesh.RecalculateNormals();mesh.RecalculateBounds();return Save(mesh,"WeatheredLimestone"+seed);}
    static void Kit(string kit,string name,float x,float z,float scale,Transform parent,bool collider=false){var m=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Tidehaven/Meshes/Kit_"+kit+".asset");if(!m)return;var go=Obj(name,m,vertex,parent);go.transform.position=Land(x,z);go.transform.rotation=Quaternion.Euler(0,R(0,360),0);go.transform.localScale=Vector3.one*scale;if(collider){var col=go.AddComponent<CapsuleCollider>();col.center=new Vector3(0,.8f,0);col.height=1.6f;col.radius=.17f;}}
    static bool Clear(float x,float z,float margin=2){return CoastalIslandLayout.PathDistance(x,z)>margin&&Vector2.Distance(new Vector2(x,z),new Vector2(-13,23))>4.5f&&Vector2.Distance(new Vector2(x,z),new Vector2(13,25))>4.5f;}
    static void MeadowMask(){const int size=1024;var pixels=new byte[size*size];for(int y=0;y<size;y++)for(int x=0;x<size;x++)pixels[y*size+x]=(byte)Mathf.RoundToInt(CoastalIslandLayout.Grass(-55+(x+.5f)*110/size,-47.6f+(y+.5f)*95.2f/size)*255);var tex=new Texture2D(size,size,TextureFormat.R8,true,true){name="Meadow path coverage",wrapMode=TextureWrapMode.Clamp,filterMode=FilterMode.Trilinear,anisoLevel=4};tex.SetPixelData(pixels,0);tex.Apply(true,false);var old=AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/MeadowCoverage.asset");if(old){EditorUtility.CopySerialized(tex,old);Object.DestroyImmediate(tex);tex=old;}else AssetDatabase.CreateAsset(tex,Folder+"/MeadowCoverage.asset");ground.SetTexture("_MeadowMask",tex);ground.SetVector("_MeadowMaskRect",new Vector4(-55,-47.6f,110,95.2f));ground.SetFloat("_UseMeadowMask",1);EditorUtility.SetDirty(ground);}
    static void VergeFlowers(Transform parent){var pieces=new List<CombineInstance>();var mesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Tidehaven/Meshes/Kit_Wildflower_Patch.asset");var grass=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Tidehaven/Meshes/Kit_Grass_TuftCluster.asset");for(int i=0;i<1250;i++){float x=R(-25,25),z=R(6,38);float dist=CoastalIslandLayout.PathDistance(x,z);if(CoastalIslandLayout.Grass(x,z)<.8f||!Clear(x,z,1.2f)||dist>3.8f&&z-TidehavenGame.Shore(x)>10)continue;float scale=R(.48f,.8f);pieces.Add(new CombineInstance{mesh=i%3==0?grass:mesh,transform=Matrix4x4.TRS(Land(x,z)+Vector3.up*.02f,Quaternion.Euler(0,R(0,360),0),Vector3.one*scale)});}var joined=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};joined.CombineMeshes(pieces.ToArray(),true,true);Obj("Soft flowering trail verges",Save(joined,"VergeWildflowers"),vertex,parent);}
    static void ScatterFlora(Transform parent){var combine=new List<CombineInstance>();foreach(var kind in new[]{"Grass_TuftCluster","Wildflower_Patch"}){var mesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Tidehaven/Meshes/Kit_"+kind+".asset");for(int i=0;i<(kind.StartsWith("Grass")?360:125);i++){float x=R(-26,26),z=R(6,41);if(CoastalIslandLayout.Grass(x,z)<.80f||!Clear(x,z,1.3f))continue;float s=kind.StartsWith("Grass")?R(.22f,.5f):R(.3f,.56f);combine.Add(new CombineInstance{mesh=mesh,transform=Matrix4x4.TRS(Land(x,z)+Vector3.up*.025f,Quaternion.Euler(0,R(0,360),0),Vector3.one*s)});}}var combined=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};combined.CombineMeshes(combine.ToArray(),true,true);Obj("Meadow grasses • ivory and buttercup flowers",Save(combined,"MeadowFlora"),vertex,parent);}

    static float OldHeight(float x,float z){float d=z-TidehavenGame.Shore(x);float hill=(2.5f*Mathf.Exp(-((x+12)*(x+12)/65f+(z-12)*(z-12)/42f))+3.1f*Mathf.Exp(-((x-13)*(x-13)/48f+(z-16)*(z-16)/55f)))*Mathf.SmoothStep(0,1,(d-3)/5);return d>=3?.85f+Mathf.PerlinNoise(x*.09f+50,z*.09f+50)*.22f+hill:d>=0?Mathf.SmoothStep(0,.95f,d/3):Mathf.Max(-3.4f,d*.22f);}
    static Mesh CliffWall(){int n=120;var vs=new List<Vector3>();var cs=new List<Color>();var ts=new List<int>();float[] ys={0,.12f,.42f,.71f,.94f,1,1};for(int j=0;j<7;j++)for(int i=0;i<=n;i++){float x=-28+56f*i/n;float z=20.5f+Mathf.Sin(x*.24f)*.65f+Mathf.Sin(x*.73f)*.22f;float h=3.7f+Mathf.Sin(x*.31f)*.48f+Mathf.Sin(x*.9f)*.18f;float baseY=CoastalIslandLayout.Height(x,z)-.35f;float bulge=Mathf.Sin(j*.9f+x*.75f)*.16f;z+=j==6?5:j==5?.38f:j==0?.4f:bulge;vs.Add(new Vector3(x+Mathf.Sin(x*2+j)*.06f,baseY+h*ys[j],z));cs.Add(j>=5?C("#688E42"):C("#939F94"));}for(int j=0;j<6;j++)for(int i=0;i<n;i++){int a=j*(n+1)+i;ts.AddRange(new[]{a,a+n+1,a+1,a+1,a+n+1,a+n+2});}var m=new Mesh();m.SetVertices(vs);m.SetColors(cs);m.SetTriangles(ts,0);m.RecalculateNormals();m.RecalculateBounds();return Save(m,"CompactCoastalCliff");}
    static void DockSurface(Transform dock,string name,Vector3 center,Vector3 size){var o=new GameObject(name);o.transform.SetParent(dock,true);o.transform.position=center;var c=o.AddComponent<BoxCollider>();c.size=size;o.AddComponent<CoastalWalkableSurface>();}

    [MenuItem("Tidehaven/Restore compact planted cove")]
    public static string Compact(){if(EditorApplication.isPlaying)throw new System.InvalidOperationException("Exit Play first");rng=new System.Random(5350560);var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
        var expanded=GameObject.Find("Expanded island • meadow village and coral gardens");if(expanded){var gardens=expanded.transform.Find("Lagoon coral gardens");if(gardens)gardens.SetParent(GameObject.Find("Living reef").transform,true);Object.DestroyImmediate(expanded);}
        var prior=GameObject.Find("Compact cove • planted gardens and rock wall");if(prior)Object.DestroyImmediate(prior);root=new GameObject("Compact cove • planted gardens and rock wall").transform;
        vertex=AssetDatabase.LoadAssetAtPath<Material>("Assets/Tidehaven/Materials/StylizedPropOutlined.mat");ground=AssetDatabase.LoadAssetAtPath<Material>("Assets/Tidehaven/Materials/CoastalGround.mat");var terrain=GameObject.Find("Sandy coast and seabed");var land=Terrain();terrain.GetComponent<MeshFilter>().sharedMesh=land;terrain.GetComponent<MeshCollider>().sharedMesh=land;MeadowMask();
        var nature=GameObject.Find("Nature • palms, grasses and shore rocks");foreach(Transform t in nature.transform){bool main=t.name=="Palm"||t.name=="BerryBush"||t.name=="Boulder"||t.name=="Crab"||t.name=="Starfish";t.gameObject.SetActive(main);if(main&&t.position.z>4){PlaceBottom(t.gameObject,t.position.x,t.position.z,.08f);}}
        // Restore the original dense ground plants, reprojecting their authored bases onto the compact land.
        foreach(var source in nature.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.name=="Combined Meadow Grasses and Wildflowers"||f.name.EndsWith("grove grasses")||f.name=="Northern gardens grasses")){
            if(source.name=="Northern gardens grasses")continue;var clone=Object.Instantiate(source.sharedMesh);var vs=clone.vertices;for(int i=0;i<vs.Length;i++){var p=source.transform.TransformPoint(vs[i]);p.y+=CoastalIslandLayout.Height(p.x,p.z)-OldHeight(p.x,p.z);vs[i]=p;}clone.vertices=vs;clone.RecalculateBounds();var go=Obj("Restored "+source.name,Save(clone,"Restored_"+source.name.Replace(" ","_")),vertex,root);}
        var floral=new List<CombineInstance>();var gm=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Tidehaven/Meshes/Kit_Grass_TuftCluster.asset");var fm=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Tidehaven/Meshes/Kit_Wildflower_Patch.asset");for(int i=0;i<650;i++){float x=R(-25,25),z=R(4,19);if(CoastalIslandLayout.Grass(x,z)<.7f||CoastalIslandLayout.PathDistance(x,z)<.95f)continue;if(Vector2.Distance(new Vector2(x,z),new Vector2(-14,14))<3.1f||Vector2.Distance(new Vector2(x,z),new Vector2(17,14))<2.3f)continue;floral.Add(new CombineInstance{mesh=i%3==0?fm:gm,transform=Matrix4x4.TRS(Land(x,z)+Vector3.up*.02f,Quaternion.Euler(0,R(0,360),0),Vector3.one*R(.58f,.9f))});}var flora=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};flora.CombineMeshes(floral.ToArray(),true,true);Obj("Dense grass tufts and wildflower verges",Save(flora,"CompactFlora"),vertex,root);
        var rockMat=AssetDatabase.LoadAssetAtPath<Material>(Folder+"/Limestone.mat");if(!rockMat){rockMat=new Material(Shader.Find("Tidehaven/Weathered Limestone"));AssetDatabase.CreateAsset(rockMat,Folder+"/Limestone.mat");}var wall=Obj("Grass topped coastal rock wall",CliffWall(),rockMat,root);wall.AddComponent<MeshCollider>().sharedMesh=wall.GetComponent<MeshFilter>().sharedMesh;
        for(int i=0;i<14;i++){float x=-27+i*4.1f;if(Mathf.Abs(x-1)<3)continue;var face=Obj("Weathered cliff outcrop",Rock(2+i%3*3),rockMat,root);face.transform.position=Land(x,20)-Vector3.up*.15f;face.transform.localScale=new Vector3(R(1.5f,2.2f),R(2.5f,3.5f),R(.8f,1.3f));face.transform.rotation=Quaternion.Euler(0,R(-20,20),0);face.AddComponent<MeshCollider>().sharedMesh=face.GetComponent<MeshFilter>().sharedMesh;}
        // Trees form a compact backdrop above the wall rather than a sparse field across the map.
        for(int i=0;i<11;i++){float x=-25+i*5.1f;var mesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Tidehaven/Meshes/Kit_Tree_CoastalPine.asset");var tree=Obj("Clifftop coastal pine",mesh,vertex,root);tree.transform.position=new Vector3(x,5.2f,23.5f+R(0,1.3f));tree.transform.localScale=Vector3.one*R(1.15f,1.55f);tree.transform.rotation=Quaternion.Euler(0,R(0,360),0);}
        var fallSource=nature.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name=="Mountain_Waterfall");if(fallSource){var falls=Object.Instantiate(fallSource.gameObject,root);falls.name="Garden waterfall in rock wall";falls.SetActive(true);falls.transform.localScale=fallSource.localScale*.88f;PlaceBottom(falls,1,19.5f,.1f);}
        var harbor=GameObject.Find("Harbor");PlaceBottom(harbor.transform.Find("House").gameObject,-14,14,.07f);PlaceBottom(harbor.transform.Find("Shop").gameObject,17,14,.07f);
        var dock=harbor.transform.Find("Dock");foreach(var surface in dock.GetComponentsInChildren<CoastalWalkableSurface>())Object.DestroyImmediate(surface.gameObject);DockSurface(dock,"Continuous dock walkway",new Vector3(12.65f,.16f,-2.55f),new Vector3(1.9f,.18f,10.45f));DockSurface(dock,"Dock shore landing",new Vector3(12.5f,.16f,1.55f),new Vector3(5.75f,.18f,2.15f));var df=dock.GetComponentInChildren<MeshFilter>();if(!df.GetComponent<MeshCollider>())df.gameObject.AddComponent<MeshCollider>().sharedMesh=df.sharedMesh;
        var stranded=GameObject.Find("Stranded belongings rock");if(stranded){var bc=stranded.GetComponent<BoxCollider>();if(bc){var size=bc.size;bc.size=new Vector3(Mathf.Abs(size.x),Mathf.Abs(size.y),Mathf.Abs(size.z));}}
        var game=Object.FindAnyObjectByType<TidehavenGame>();game.player.position=Land(0,3.7f);game.player.GetComponent<CharacterController>().stepOffset=.35f;game.view.transform.position=game.player.position+new Vector3(0,12.4f,-10.2f);game.view.transform.rotation=Quaternion.LookRotation(new Vector3(0,-11.6f,9));game.view.orthographicSize=9.5f;
        EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();return "Compact gardens: houses Z14, wall Z20.5, original palms and plants restored; dock deck collision and shallow wading ready.";
    }

    [MenuItem("Tidehaven/Legacy expanded meadow")]
    public static string Run(){if(EditorApplication.isPlaying)throw new System.InvalidOperationException("Exit Play Mode first.");if(!AssetDatabase.IsValidFolder(Folder))AssetDatabase.CreateFolder("Assets/Tidehaven","Expansion");rng=new System.Random(5350560);
        var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(!scene.path.EndsWith("CoralCove.unity"))throw new System.InvalidOperationException("Open CoralCove first.");
        var old=GameObject.Find("Expanded island • meadow village and coral gardens");if(old)Object.DestroyImmediate(old);
        var nature=GameObject.Find("Nature • palms, grasses and shore rocks");var palm=nature.transform.Cast<Transform>().First(t=>t.name=="Palm").gameObject;var bush=nature.transform.Cast<Transform>().First(t=>t.name=="BerryBush").gameObject;
        // Retain the original authored objects for easy restoration; only their replacement is shown.
        foreach(Transform t in nature.transform){if(t.name=="Boulder"&&t.position.z<4)continue;if(t.name=="Crab"||t.name=="Starfish")continue;t.gameObject.SetActive(false);}
        root=new GameObject("Expanded island • meadow village and coral gardens").transform;
        vertex=new Material(AssetDatabase.LoadAssetAtPath<Material>("Assets/Tidehaven/Materials/StylizedPropOutlined.mat"));vertex.name="Soft woodland colors";vertex.SetFloat("_ColorVibrance",.95f);vertex.SetFloat("_OutlineWidth",0);vertex.SetColor("_BaseColor",new Color(.94f,.98f,.91f,1));var vm=AssetDatabase.LoadAssetAtPath<Material>(Folder+"/Woodland.mat");if(vm){EditorUtility.CopySerialized(vertex,vm);Object.DestroyImmediate(vertex);vertex=vm;}else AssetDatabase.CreateAsset(vertex,Folder+"/Woodland.mat");
        ground=AssetDatabase.LoadAssetAtPath<Material>("Assets/Tidehaven/Materials/CoastalGround.mat");var terrain=GameObject.Find("Sandy coast and seabed");var mesh=Terrain();Undo.RecordObject(terrain.GetComponent<MeshFilter>(),"Expand walkable meadow");terrain.GetComponent<MeshFilter>().sharedMesh=mesh;terrain.GetComponent<MeshCollider>().sharedMesh=mesh;terrain.GetComponent<Renderer>().sharedMaterial=ground;
        var trees=new GameObject("Scattered coastal woodland").transform;trees.SetParent(root,false);
        Vector2[] palms={new Vector2(-6,8),new Vector2(8,9),new Vector2(-20,8),new Vector2(22,10),new Vector2(-10,13),new Vector2(19,16),new Vector2(-22,21),new Vector2(24,25)};
        for(int i=0;i<palms.Length;i++){var p=palms[i];PlaceTemplate(palm,"Coastal palm "+(i+1),p.x,p.y,R(3.8f,5.1f),trees,true);}
        var occupied=new List<Vector2>(palms);int planted=0;for(int attempt=0;attempt<600&&planted<42;attempt++){float x=R(-26,26),z=R(11,43);var p=new Vector2(x,z);if(!Clear(x,z,2.5f)||occupied.Any(q=>Vector2.Distance(p,q)<3.6f))continue;Kit(planted%4==0?"Tree_CoastalPine":"Tree_CoastalBroadleaf","Meadow tree "+(++planted),x,z,R(.9f,1.4f),trees,true);occupied.Add(p);}
        for(int i=0;i<44;i++){float x=R(-25,25),z=R(7,40);if(!Clear(x,z,1.8f)||CoastalIslandLayout.Grass(x,z)<.8f)continue;if(i%3==0)PlaceTemplate(bush,"Berry thicket "+i,x,z,R(.5f,.9f),trees);else Kit("Shrub_GoldenOlive","Wild olive shrub "+i,x,z,R(.4f,.8f),trees);}
        ScatterFlora(root);VergeFlowers(root);MeadowMask();
        var hills=new GameObject("Distant limestone hills • open central walking route").transform;hills.SetParent(root,false);var rocks=new[]{Rock(2),Rock(5),Rock(8)};
        for(int side=-1;side<=1;side+=2)for(int i=0;i<8;i++){float x=side*(10+i*2.4f),z=29+Mathf.Sin(i*.8f)*1.7f+i*.65f;var go=Obj("Grass capped limestone terrace",rocks[i%3],vertex,hills);go.transform.position=Land(x,z)-Vector3.up*.35f;go.transform.localScale=new Vector3(R(1.6f,2.6f),R(1.3f,2.2f),R(1.5f,2.4f));go.transform.rotation=Quaternion.Euler(0,R(-25,25),0);go.AddComponent<MeshCollider>().sharedMesh=rocks[i%3];}
        for(int i=0;i<20;i++){float x=R(-25,25),z=R(9,40);if(!Clear(x,z,2))continue;var go=Obj("Mossy meadow stone",rocks[i%3],vertex,hills);go.transform.position=Land(x,z)-Vector3.up*.1f;go.transform.localScale=new Vector3(R(.45f,1f),R(.3f,.7f),R(.5f,.95f));go.transform.rotation=Quaternion.Euler(0,R(0,360),0);go.AddComponent<MeshCollider>().sharedMesh=rocks[i%3];}
        // Bring the original waterfall landmark deeper inland, beside the northern trail.
        var originalFalls=nature.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name=="Mountain_Waterfall");if(originalFalls){var falls=Object.Instantiate(originalFalls.gameObject,root);falls.name="Northern cascade landmark";falls.SetActive(true);falls.transform.localScale*=.72f;PlaceBottom(falls,-7,35);}
        var harbor=GameObject.Find("Harbor");foreach(Transform house in harbor.transform){if(house.name=="House")PlaceBottom(house.gameObject,-13,23,.07f);if(house.name=="Shop")PlaceBottom(house.gameObject,13,25,.07f);}
        var reef=GameObject.Find("Living reef");var reefTemplate=reef.transform.Cast<Transform>().First(t=>t.name=="Reef").gameObject;var coralTemplate=reef.transform.Cast<Transform>().First(t=>t.name=="Coral").gameObject;var seaweed=reef.transform.Cast<Transform>().First(t=>t.name=="Seagrass").gameObject;
        // Ground existing reef colonies on the seabed instead of burying them beneath it.
        foreach(Transform t in reef.transform){if(t.name=="Coral"||t.name=="Reef"||t.name=="Seagrass")PlaceBottom(t.gameObject,t.position.x,t.position.z,.02f);}
        var gardens=new GameObject("Lagoon coral gardens").transform;gardens.SetParent(root,false);
        Vector2[] colonies={new Vector2(-12,-2.8f),new Vector2(-17,-5.6f),new Vector2(-3,-5.6f),new Vector2(5,-4.8f),new Vector2(11,-3.8f),new Vector2(18,-3),new Vector2(22,-7),new Vector2(-22,-7)};
        for(int i=0;i<colonies.Length;i++){var p=colonies[i];float depth=-CoastalIslandLayout.Height(p.x,p.y);PlaceTemplate(reefTemplate,"Coral garden "+(i+1),p.x,p.y,Mathf.Min(R(.65f,1.15f),depth-.22f),gardens);for(int j=0;j<3;j++){float x=p.x+R(-1.7f,1.7f),z=p.y+R(-1.2f,1.2f);PlaceTemplate(j==0?coralTemplate:seaweed,j==0?"Branching coral":"Swaying eelgrass",x,z,Mathf.Min(R(.35f,.7f),-CoastalIslandLayout.Height(x,z)-.18f),gardens);}}
        var water=AssetDatabase.LoadAssetAtPath<Material>("Assets/Tidehaven/Materials/CoveWater.mat");water.SetColor("_Color_Shallow",new Color(.22f,.72f,.62f,.27f));water.SetColor("_Color_Deep",new Color(.035f,.37f,.37f,.78f));water.SetFloat("_Water_Depth",2.8f);water.SetFloat("_Depth_Distance",3.5f);water.SetFloat("_Normal_Strength",.018f);water.SetFloat("_Caustics_Strength",.23f);water.SetFloat("_Caustics_Scale",.58f);water.SetFloat("_SL_Thickness",.10f);EditorUtility.SetDirty(water);
        var game=Object.FindFirstObjectByType<TidehavenGame>();game.player.position=Land(game.player.position.x,game.player.position.z);game.player.GetComponent<CharacterController>().slopeLimit=48;
        // Frame the beach and the opening into the meadow for the saved scene.
        var cam=game.view;cam.transform.position=game.player.position+new Vector3(0,12.4f,-10.2f);cam.transform.rotation=Quaternion.LookRotation(new Vector3(0,-11.6f,9));cam.orthographicSize=9.5f;
        foreach(var m in Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None).SelectMany(r=>r.sharedMaterials).Distinct())if(m&&m.shader.name=="Tidehaven/Stylized Vertex Lit"){m.SetFloat("_ColorVibrance",.98f);m.SetFloat("_OutlineWidth",0);EditorUtility.SetDirty(m);}
        EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();return "Expanded meadow to Z38, moved village inland, added "+planted+" trees, soft limestone terraces and 8 coral gardens.";
    }
